"""DagBag integrity tests — the CI contract for every DAG in this repo.

These run on every PR (see .github/workflows/ci.yml) and catch the three
ways DAG changes actually break production: import errors at parse time,
silently missing DAGs (a config typo in dag_factory), and missing
operational hygiene (retries/tags).
"""

import pytest
from airflow.models import DagBag

from conftest import DAGS

EXPECTED_DAGS = {
    "etl_payments",            # generated by dag_factory from pipeline_config.yml
    "etl_refunds",
    "etl_customers",
    "payments_daily_taskflow",  # hand-written TaskFlow DAG
    "backfill_payments",        # trigger-only backfill
}


@pytest.fixture(scope="module")
def dagbag() -> DagBag:
    return DagBag(dag_folder=str(DAGS), include_examples=False)


def test_no_import_errors(dagbag: DagBag) -> None:
    assert not dagbag.import_errors, f"DAG import errors: {dagbag.import_errors}"


def test_all_expected_dags_present(dagbag: DagBag) -> None:
    assert EXPECTED_DAGS <= set(dagbag.dag_ids), (
        f"missing DAGs: {EXPECTED_DAGS - set(dagbag.dag_ids)}")


def test_every_dag_has_tags_and_retries(dagbag: DagBag) -> None:
    for dag in dagbag.dags.values():
        assert dag.tags, f"{dag.dag_id} has no tags"
        for task in dag.tasks:
            assert task.retries and task.retries >= 1, (
                f"{dag.dag_id}.{task.task_id} has no retries configured")


def test_generated_dags_have_the_platform_graph(dagbag: DagBag) -> None:
    for dag_id in ("etl_payments", "etl_refunds", "etl_customers"):
        dag = dagbag.dags[dag_id]
        assert dag is not None
        assert {t.task_id for t in dag.tasks} == {
            "wait_for_extract", "quality_gate", "load", "verify"}
        gate = dag.get_task("quality_gate")
        load = dag.get_task("load")
        assert "load" in gate.downstream_task_ids
        assert "verify" in load.downstream_task_ids


def test_backfill_is_trigger_only(dagbag: DagBag) -> None:
    dag = dagbag.dags["backfill_payments"]
    assert dag is not None
    assert dag.schedule_interval is None
    assert dag.catchup is False
